class Buch:
    def __init__(self, titel, seiten):
        self.titel = titel
        self.seiten = seiten

    def __str__(self):
        return f"„{self.titel}“ ({self.seiten} Seiten)"

    def __repr__(self):
        return f"Buch('{self.titel}', {self.seiten})"

b = Buch("Momo", 300)
print(b)        # „Momo“ (300 Seiten)
print([b])      # [Buch('Momo', 300)]

class Punkt:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

print(Punkt(1, 2) == Punkt(1, 2))   # True (ohne __eq__ wäre es False)

class Playlist:
    def __init__(self):
        self.songs = []

    def __len__(self):
        return len(self.songs)

p = Playlist()
p.songs.append("Song A")
p.songs.append("Song B")
print(len(p))   # 2

class Pruefung:
    def __init__(self, fach, note):
        self.fach = fach
        self.note = note          # nutzt schon den Setter!

    @property
    def note(self):
        return self._note

    @note.setter
    def note(self, wert):
        if wert < 1 or wert > 5:
            raise ValueError("Note muss zwischen 1 und 5 liegen")
        self._note = wert

    @property
    def bestanden(self):          # nur lesbar, wird berechnet
        return self.note < 5

p = Pruefung("Mathe", 2)
print(p.note, p.bestanden)   # 2 True
p.note = 5
print(p.bestanden)           # False
p.note = 7                   # ValueError: Note muss zwischen 1 und 5 liegen

