class Stadt:
    def __init__(self, name, ew):
        self.name = name
        self.ew = ew

    def __str__(self):
        return f"{self.name} ({self.ew} EW)"

    def __repr__(self):
        return f"Stadt('{self.name}')"

print([Stadt("Wien", 2000000)])

class Karte:
    def __init__(self, wert):
        self.wert = wert

a = Karte(10)
b = Karte(10)
print(a == b)

class Team:
    def __init__(self, groesse):
        self.groesse = groesse

    def __str__(self):
        print(f"Team: {self.groesse}")

t = Team(4)
print(t)

class Lager:
    def __init__(self):
        self._wert = 10

    @property
    def wert(self):
        return self._wert

    @wert.setter
    def wert(self, neu):
        if neu < 0:
            raise ValueError("negativ")
        self._wert = neu

l = Lager()
l.wert = 20
l.wert = -5
print(l.wert)
